    display: inline-flex;
    align-items: center;
    gap: 0.2rem;
    padding: 0.15rem 0.5rem;
    font-size: 0.8rem;
    background: #f0f0f0;
    border: 1px solid #ddd;
    border-radius: 12px;
    cursor: pointer;
}

.reaction-badge:hover {
    background: #e0e8f0;
    border-color: #1264a3;
}

.thread-link {
    display: inline-block;
    margin-top: 0.3rem;
    background: none;
    border: none;
    color: #1264a3;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    padding: 0;
}

.thread-link:hover {
    text-decoration: underline;
}

.action-bar {
    position: absolute;
