@using sv_70b42aa5c9094f5a9c15239bd6a0da74.Services

<div class="channel-list">
    <h3 class="sidebar-title">Channels</h3>

    @foreach (var channel in Channels)
    {
        <button class="channel-item @(channel.Id == ActiveChannelId ? "active" : "")"
                @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
            <div class="channel-name-row">
                <span class="channel-name"># @channel.Name</span>
                @if (channel.UnreadCount > 0)
                {
                    <span class="unread-badge">@channel.UnreadCount</span>
                }
            </div>
            <span class="channel-desc">@TruncateDescription(channel.Description)</span>
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string TruncateDescription(string desc)
        => desc.Length > 40 ? desc[..37] + "…" : desc;
}

.channel-list {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #3f0e40;
    color: #cfc3cf;
    overflow-y: auto;
}

.sidebar-title {
    padding: 1rem 1rem 0.5rem;
    font-size: 1.1rem;
    font-weight: 700;
    color: #fff;
    margin: 0;
}

.channel-item {
    display: flex;
    flex-direction: column;
    width: 100%;
    padding: 0.5rem 1rem;
    background: none;
    border: none;
    text-align: left;
    color: #cfc3cf;
    cursor: pointer;
    border-radius: 0;
    font-family: inherit;
    font-size: inherit;
}

.channel-item:hover {
    background: rgba(255, 255, 255, 0.08);
}

.channel-item.active {
    background: #1164a3;
    color: #fff;
}

.channel-name-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
}

.channel-item.active .channel-name {
    color: #fff;
}

.unread-badge {
    background: #cd2553;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.1rem 0.45rem;
    border-radius: 10px;
    min-width: 1.2rem;
    text-align: center;
}

.channel-desc {
    font-size: 0.75rem;
    opacity: 0.7;
    margin-top: 0.1rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

@using sv_70b42aa5c9094f5a9c15239bd6a0da74.Services

<div class="thread-panel">
    <div class="thread-header">
        <h4>Thread</h4>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <MessageItem Message="RootMessage"
                         OnReact="OnReactToMessage" />
        </div>

        <div class="thread-divider">
            <span>@ThreadMessages.Count @(ThreadMessages.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-messages">
            @foreach (var msg in ThreadMessages)
            {
                <MessageItem Message="msg"
                             OnReact="OnReactToMessage" />
            }
        </div>

        <MessageInput Placeholder="Reply…"
                      ButtonLabel="Reply"
                      OnSubmit="OnSendReply" />
    }
</div>

@code {
    [Parameter, EditorRequired] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> ThreadMessages { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
    [Parameter] public EventCallback<string> OnReactToMessage { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    border-left: 1px solid #ddd;
    background: #fff;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e0e0e0;
}

.thread-header h4 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    color: #666;
    cursor: pointer;
    padding: 0.2rem 0.4rem;
    border-radius: 4px;
}

.close-btn:hover {
    background: #f0f0f0;
    color: #333;
}

.thread-root {
    padding: 0.5rem 0;
    border-bottom: 1px solid #e0e0e0;
    background: #fafafa;
}

.thread-divider {
    display: flex;
    align-items: center;
    padding: 0.4rem 1rem;
    font-size: 0.75rem;
    color: #888;
    font-weight: 600;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 0.25rem 0;
}

