    min-width: 200px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: #fff;
}

.chat-main.full-width {
    /* When no thread panel is open, main takes remaining space */
}

.chat-thread {
