    background: #fff;
}

.channel-header h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1d1c1d;
}

.channel-description {
    font-size: 0.8rem;
    color: #888;
}

/* Message list */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

.loading-indicator {
    text-align: center;
    padding: 0.75rem;
    color: #888;
    font-size: 0.85rem;
}

.no-channel {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #888;
    font-size: 1.1rem;
}

