    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();

        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        threadReplyCounts = new();
        hasMoreMessages = true;
        CloseThread();

        if (activeChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
            hasMoreMessages = messages.Count >= PageSize;
            await BuildThreadReplyCounts();
            await ChatService.MarkChannelReadAsync(channelId);
            UpdateChannelUnread(channelId);
        }
    }

    private async Task HandleScroll()
    {
        // Triggered on scroll — load more when near top
        if (isLoadingMore || !hasMoreMessages) return;

        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(activeChannelId, messages.Count, PageSize);
        if (older.Count < PageSize) hasMoreMessages = false;
        messages.InsertRange(0, older);
        await BuildThreadReplyCounts();

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(Message msg)
    {
        // If the message is a reply, open the root thread instead
        var rootId = msg.ReplyToId ?? msg.Id;
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootId) ?? msg;
        threadMessages = await ChatService.GetThreadAsync(rootId);
    }

    private void CloseThread()
    {
        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
        threadMessages.Add(reply);

        // Update reply count in main view
        threadReplyCounts[threadRootMessage.Id] = threadMessages.Count;
    }

    private async Task AddReaction(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        // Refresh the affected message in our local list
        await RefreshMessage(messageId);
    }

    private async Task RefreshMessage(int messageId)
    {
        // Reload messages for the channel to pick up reaction changes
        var refreshed = await ChatService.GetMessagesAsync(activeChannelId, 0, messages.Count);
        if (refreshed.Count > 0) messages = refreshed;
    }

    private async Task BuildThreadReplyCounts()
    {
        // For each root message (ReplyToId == null), count replies in the loaded set
        // Also use GetThreadAsync for messages that have known replies
        foreach (var msg in messages.Where(m => m.ReplyToId is null))
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            if (thread.Count > 0)
            {
                threadReplyCounts[msg.Id] = thread.Count;
            }
        }
    }

    private void UpdateChannelUnread(int channelId)
    {
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = channels[idx];
            channels[idx] = ch with { UnreadCount = 0 };
        }
    }

    public ValueTask DisposeAsync()
    {
        cts.Cancel();
        cts.Dispose();
        return ValueTask.CompletedTask;
    }
}

